/**
 * @name Insecure deserialization with pickle
 * @description Using pickle to deserialize untrusted data can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id python/insecure-deserialization
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module InsecureDeserializationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("pickle").getMember(["loads", "load", "Unpickler"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module InsecureDeserializationFlow = TaintTracking::Global<InsecureDeserializationConfig>;
import InsecureDeserializationFlow::PathGraph

from InsecureDeserializationFlow::PathNode source, InsecureDeserializationFlow::PathNode sink
where InsecureDeserializationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure deserialization from $@.", source.getNode(), "untrusted source"

/**
 * @name SQL injection
 * @description User-controlled data used in SQL query without sanitization
 * @kind path-problem
 * @problem.severity error
 * @id python/sql-injection
 * @tags security
 *       external/cwe/cwe-89
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts
import semmle.python.dataflow.new.RemoteFlowSources

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SQL query constructed from $@.", source.getNode(), "user-controlled data"
